-- migrate:up
-- Directus field metadata for the ④b per-method test fields. Conditional on
-- test_type so each method's panel appears only for that test. Idempotent: clears
-- any previously-inserted rows for these prefixes before re-inserting.

BEGIN;

DELETE FROM directus_fields WHERE collection='test_sessions' AND (field LIKE 'tribology\_%' OR field LIKE 'optical_microscopy\_%' OR field LIKE 'tem\_%' OR field LIKE 'alicona\_%' OR field LIKE 'clemx\_%' OR field LIKE 'dct\_%' OR field LIKE 'ct_scan\_%' OR field LIKE 'fatigue\_%' OR field LIKE 'creep\_%' OR field LIKE 'dma\_%');

-- ── tribology → test_sessions (inline, shows when test_type=tribology) ──

-- ── optical_microscopy → test_sessions (inline, shows when test_type=optical_microscopy) ──

-- ── tem → test_sessions (inline, shows when test_type=tem) ──

-- ── alicona → test_sessions (inline, shows when test_type=alicona) ──

-- ── clemx → test_sessions (inline, shows when test_type=clemx) ──

-- ── dct → test_sessions (inline, shows when test_type=dct) ──

-- ── ct_scan → test_sessions (inline, shows when test_type=ct_scan) ──

-- ── fatigue → test_sessions (inline, shows when test_type=fatigue) ──

-- ── creep → test_sessions (inline, shows when test_type=creep) ──

-- ── dma → test_sessions (inline, shows when test_type=dma) ──

COMMIT;

-- migrate:down
DELETE FROM directus_fields WHERE collection='test_sessions' AND (field LIKE 'tribology\_%' OR field LIKE 'optical_microscopy\_%' OR field LIKE 'tem\_%' OR field LIKE 'alicona\_%' OR field LIKE 'clemx\_%' OR field LIKE 'dct\_%' OR field LIKE 'ct_scan\_%' OR field LIKE 'fatigue\_%' OR field LIKE 'creep\_%' OR field LIKE 'dma\_%');
